# ------------------------------------------------------------------ appendix texts
APP1_INTRO = ("هر جدول یک بخش را می‌گوید. «اصلی» یعنی کاشی در «شاخص‌های اصلی» بالای صفحه هم هست. ستون «قاعده‌ی رنگ» آستانه‌هاست؛ همه‌ی آستانه‌ها ★اند و شرکت باید آن‌ها را تایید کند (جدول ★). ستون «جمله‌ی زیر عدد» متن توضیح همان کاشی است (N، X و Y عددهای روزند). ستون آخر می‌گوید عدد را از کدام جدول جزئیات و چگونه می‌شود دوباره شمرد. شاخص‌هایی که «بدون وضعیت» نوشته‌اند کاشی خاکستری و بدون نشان دارند. کلید لاتین زیر هر عنوان نام فنی شاخص در رابط است.")
APP2_INTRO = ("بیست‌ویک نمودار در نُه بخش. همه‌ی نمودارها نماد «جدول اعداد» (دکمه‌ی نمایش جدول) و نماد «ریز رکوردها» (جدول جزئیات مربوط به همان نمودار) دارند. ستون آخر متن «یادداشت زیر نمودار» است.")
APP3_INTRO = ("سی‌وهشت هشدار ممکن به ترتیب گروه‌ها (بحرانی، هشدار، اطلاع). N و X در جمله‌ها عددهای روزند. ستون «برابر با» می‌گوید عدد جمله با کدام شاخص صفحه یکی است («—» یعنی شاخص هم‌ارز در صفحه نیست و عدد را از صفحه‌ی همان ماژول بسنجید). ترتیب ردیف‌ها داخل هر گروه در صفحه‌ی شما ممکن است با این جدول فرق کند؛ جمله‌ها همان‌اند.")
APP4_INTRO = ("شصت‌وهشت جدول جزئیات در ده گروه به ترتیب فهرست «همه‌ی جدول‌های جزئیات». برای هر جدول: کلید لاتین (در رابط و در دستورها)، توضیح، پارامترها (فیلترها؛ فقط جدول‌های دارای پارامتر)، ستون‌ها به ترتیب صفحه، یادداشت زیر عنوان و صفحه‌ی ماژولی که «باز کردن صفحه‌ی ماژول» به آن می‌رود. صفحه‌ی داشبورد جدول‌ها را بدون فیلتر باز می‌کند؛ فیلتر را فقط دستیار (فرمان‌هایی مثل «نشانم بده پروژه‌های قرمز») یا رابط برنامه‌نویسی می‌فرستد. هر جدول ردیف‌های همین امروز را نشان می‌دهد؛ جدول بدون ردیف پیام «ردیفی برای نمایش نیست؛ هیچ رکوردی در این جدول با شرایط امروز جور نیست.» دارد.")
APP5_INTRO = ("مثال با عددهای ساختگی نشان می‌دهد تستر چگونه چند شاخص را از صفحه‌ی ماژول‌ها دوباره حساب می‌کند. عددهای بخش‌ها همه با هم سازگارند (از یک مثال‌اند) و فقط برای فهمیدن قاعده‌اند؛ عدد پایگاه شما فرق می‌کند. تفاوت کوچک از گرد کردن است: سامانه عدد کامل را نگه می‌دارد و فقط هنگام نوشتن یک رقم اعشار (برای «میلیارد ریال») گرد می‌کند.")
APP6_INTRO = ("دستورهای آزمون‌های نشان‌دارِ «(ویژه‌ی مدیر فنی)». هیچ‌کدام را بدون خواندن اجرا نکنید و فقط روی پایگاه و سرور آزمایشی بزنید. این دستورها هنگام تهیه‌ی بسته روی ویندوز و SQL Server واقعی اجرا نشده‌اند (ماشین تهیه‌ی بسته ویندوز ندارد)؛ اگر دستوری خطا داد یا نتیجه‌ی دیگری آورد، متن خطا را در توضیح آزمون بنویسید.")

